import{_ as t,c as a,o as d,ag as o}from"./chunks/framework.Bw-5EFTY.js";const m=JSON.parse('{"title":"resAppend","description":"","frontmatter":{},"headers":[],"relativePath":"docs/rules/resAppend.md","filePath":"docs/rules/resAppend.md"}'),s={name:"docs/rules/resAppend.md"};function l(p,e,c,n,r,i){return d(),a("div",null,e[0]||(e[0]=[o('<h1 id="resappend" tabindex="-1">resAppend <a class="header-anchor" href="#resappend" aria-label="Permalink to &quot;resAppend&quot;">​</a></h1><p>在现有响应内容体后面插入指定内容（仅对包含响应内容体的状态码有效，如 <code>200</code>/<code>500</code> 等）</p><blockquote><p>⚠️ 注意：204、304 等无响应内容体的请求不受影响</p></blockquote><h2 id="规则语法" tabindex="-1">规则语法 <a class="header-anchor" href="#规则语法" aria-label="Permalink to &quot;规则语法&quot;">​</a></h2><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>pattern resAppend://value [filters...]</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>描述</th><th>详细文档</th></tr></thead><tbody><tr><td>pattern</td><td>匹配请求 URL 的表达式</td><td><a href="./pattern.html">匹配模式文档</a></td></tr><tr><td>value</td><td>文本或二进制内容，支持以下类型：<br>• 目录/文件路径<br>• 远程 URL<br>• 内联/内嵌/Values内容</td><td><a href="./operation.html">操作指令文档</a></td></tr><tr><td>filters</td><td>可选过滤器，支持匹配：<br>• 请求URL/方法/头部/内容<br>• 响应状态码/头部</td><td><a href="./filters.html">过滤器文档</a></td></tr></tbody></table><h2 id="配置示例" tabindex="-1">配置示例 <a class="header-anchor" href="#配置示例" aria-label="Permalink to &quot;配置示例&quot;">​</a></h2><h4 id="内联方式" tabindex="-1">内联方式 <a class="header-anchor" href="#内联方式" aria-label="Permalink to &quot;内联方式&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>www.example.com/path resAppend://(Hello) file://(-test-)</span></span></code></pre></div><p>请求 <code>https://www.example.com/path/to</code> 响应内容变成 <code>-test-Hello</code>。</p><h4 id="内嵌-values方式" tabindex="-1">内嵌/Values方式 <a class="header-anchor" href="#内嵌-values方式" aria-label="Permalink to &quot;内嵌/Values方式&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>``` body.txt</span></span>\n<span class="line"><span>Hello world.</span></span>\n<span class="line"><span>```</span></span>\n<span class="line"><span>www.example.com/path resAppend://{body.txt} file://(-test-)</span></span></code></pre></div><p>请求 <code>https://www.example.com/path/to</code> 响应内容变成 <code>-test-Hello world.</code>。</p><h4 id="本地-远程资源" tabindex="-1">本地/远程资源 <a class="header-anchor" href="#本地-远程资源" aria-label="Permalink to &quot;本地/远程资源&quot;">​</a></h4><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>www.example.com/path1 resAppend:///User/xxx/test.txt</span></span>\n<span class="line"><span>www.example.com/path2 resAppend://https://www.xxx.com/xxx/params.txt</span></span>\n<span class="line"><span># 通过编辑临时文件</span></span>\n<span class="line"><span>www.example.com/path3 resAppend://temp/blank.txt</span></span></code></pre></div><h2 id="related" tabindex="-1">关联协议 <a class="header-anchor" href="#related" aria-label="Permalink to &quot;关联协议 {#related}&quot;">​</a></h2><ol><li>在响应内容前注入内容（<code>Prepend To Body</code>）：<a href="./resPrepend.html">resPrepend</a></li><li>在响应内容前注入 HTML 内容（<code>Prepend HTML To Body</code>，响应类型必须为 <code>text/html</code>）：<a href="./htmlPrepend.html">htmlPrepend</a></li><li>在响应内容前注入 CSS 内容（<code>Prepend CSS To Body</code>，响应类型必须为 <code>text/html</code> 或 <code>text/css</code>）：<a href="./cssPrepend.html">cssPrepend</a></li><li>在响应内容前注入 JS 内容（<code>Prepend JS To Body</code>，响应类型必须为 <code>text/html</code>、<code>text/css</code> 或 <code>application/javascript</code>）：<a href="./jsPrepend.html">jsPrepend</a></li><li>替换响应内容（<code>Replace Body</code>）：<a href="./resBody.html">resBody</a></li><li>用 HTML 内容替换响应内容（<code>Replace Body</code>，响应类型必须为 <code>text/html</code>）：<a href="./htmlBody.html">htmlBody</a></li><li>用 CSS 内容替换响应内容（<code>Replace Body</code>，响应类型必须为 <code>text/html</code> 或 <code>text/css</code>）：<a href="./cssBody.html">cssBody</a></li><li>用 JS 内容替换响应内容（<code>Replace Body</code>，响应类型必须为 <code>text/html</code>、<code>text/css</code> 或 <code>application/javascript</code>）：<a href="./jsBody.html">jsBody</a></li><li>在响应内容后追加内容（<code>Append To Body</code>）：<a href="./resAppend.html">resAppend</a></li><li>在响应内容后追加 HTML 内容（<code>Append HTML To Body</code>，响应类型必须为 <code>text/html</code>）：<a href="./htmlAppend.html">htmlAppend</a></li><li>在响应内容后追加 CSS 内容（<code>Append CSS To Body</code>，响应类型必须为 <code>text/html</code> 或 <code>text/css</code>）：<a href="./cssAppend.html">cssAppend</a></li><li>在响应内容后追加 JS 内容（<code>Append JS To Body</code>，响应类型必须为 <code>text/html</code>、<code>text/css</code> 或 <code>application/javascript</code>）：<a href="./jsAppend.html">jsAppend</a></li><li>使用关键字或正则表达式替换响应内容（<code>Modify Body Text</code>）：<a href="./resReplace.html">resReplace</a></li><li>覆盖响应内容中的 JSON/Form 对象（<code>Modify Form/JSON</code>）：<a href="./resMerge.html">resMerge</a></li><li>删除响应内容中的 JSON/Form 对象属性（<code>Delete Form/JSON</code>）：<a href="./delete.html">delete://resBody.xxx</a></li></ol>',17)]))}const x=t(s,[["render",l]]);export{m as __pageData,x as default};
